export function ColourDemo({
  colorValue = "{{colorValue}}",
  onBackground = {{onBackground}},
  onText = {{onText}},
  onBorder = {{onBorder}},
}) {
  const chip = { flex: 1, height: 64, borderRadius: 8, border: "3px solid transparent", background: "#FAF7F2", display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 700, boxSizing: "border-box" };
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 300 }}>
      <div style={{ display: "flex", gap: 10 }}>
        <div style={{ ...chip, background: onBackground ? colorValue : "#e5e5e5" }}>bg</div>
        <div style={{ ...chip, color: onText ? colorValue : "#999999" }}>text</div>
        <div style={{ ...chip, borderColor: onBorder ? colorValue : "#cccccc" }}>border</div>
      </div>
      <p style={{ marginTop: 12, fontSize: 12, color: "#241430cc" }}>One value, {colorValue}, applied wherever a colour property accepts it.</p>
    </div>
  );
}
